        },
        {
            "content": "클라우드 인프라 비용 절감 방안 마련",
            "assignee": "송지호",
            "due_date": ""
        },
        {
            "content": "대체 서비스 조사 및 시나리오 플래닝",
            "assignee": "전체 팀",
            "due_date": ""
        }
    ],
    "risks": [
        {
            "description": "클라우드 서비스 제공업체의 가격 변동 가능성",
            "level": "중",
            "regulation": "대체 서비스 조사 및 시나리오 플래닝"
        }
    ]
}

{
    "title": "KMT 제조업체 고객 VOC 대응 회의록",
    "date": "2023-11-15",
    "attendees": [
        "김영준",
        "이서현",
        "박지훈",
